<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';require_once __DIR__.'/pwa_step24.php';$error=null;$order=null;$code=trim((string)($_POST['code']??''));$token=trim((string)($_POST['token']??''));if($_SERVER['REQUEST_METHOD']==='POST'&&$code!==''&&$token!==''){try{$pdo=ps23_db();$order=ps23_status($pdo,$code,$token);}catch(Throwable $e){$error=$e->getMessage();}}function st_label(string $status):string{return match($status){'submitted'=>'Submitted','reviewing'=>'Under Review','confirmed'=>'Confirmed','quote_ready'=>'Quote Ready','converted'=>'Converted to Sale','cancelled'=>'Cancelled',default=>ucwords(str_replace('_',' ',$status))};}?><!doctype html><html lang="en-IN"><head><?php s24_head('Track Order Request - Healthcare Wellness Club','Privately track a Healthcare Wellness Club product order request using its code and tracking key.','status.php','noindex,nofollow,noarchive');?></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club" width="42" height="42"><span><strong>Healthcare Wellness Club</strong><small>Order Request Tracking</small></span></a><nav class="store-actions" aria-label="Tracking actions"><a class="store-btn primary" href="index.php">Products</a></nav></div></header><main class="store-shell" id="main-content"><section class="store-hero" aria-labelledby="tracking-title"><div class="store-kicker">PRIVATE TRACKING</div><h1 id="tracking-title">Track a product order request.</h1><p>Use your Order Request Code and private tracking key. The key is stored only as a one-way hash by the server, so keep your copy safe.</p></section><?php if($error):?><div class="notice bad" role="alert"><?=ps23_h($error)?></div><?php endif;?><?php if(!$order):?><section class="card track-form" style="max-width:720px;margin:16px auto"><form method="post" autocomplete="off"><label for="orderCode">Order Request Code<input class="store-input" id="orderCode" name="code" value="<?=ps23_h($code)?>" placeholder="WEB-..." autocapitalize="characters" spellcheck="false" required></label><label for="trackingToken" style="display:block;margin-top:12px">Private Tracking Key<input class="store-input" id="trackingToken" name="token" value="<?=ps23_h($token)?>" autocomplete="off" autocapitalize="none" spellcheck="false" required></label><button class="store-btn primary" type="submit" style="width:100%;margin-top:12px">Track Request</button></form><div class="notice">Do not share your tracking key publicly.</div></section><?php else:?><section class="two-col" style="margin-top:16px"><article class="card"><div class="store-kicker">ORDER REQUEST</div><div class="order-code"><?=ps23_h($order['order_code'])?></div><?php if((string)($_POST['created']??'')==='1'):?><div class="notice">Request saved successfully. Save your Order Request Code and tracking key before leaving this page.</div><?php endif;?><div class="summary-line"><span>Status</span><strong><?=ps23_h(st_label((string)$order['order_status']))?></strong></div><div class="summary-line"><span>Payment</span><strong><?=ps23_h(ucwords(str_replace('_',' ',(string)$order['payment_status'])))?></strong></div><div class="summary-line"><span>Delivery</span><strong><?=ps23_h(ucwords(str_replace('_',' ',(string)$order['delivery_mode'])))?></strong></div><div class="summary-line"><span>MRP subtotal</span><strong><?=ps23_money($order['subtotal_mrp'])?></strong></div><div class="summary-line"><span>Delivery charge</span><strong><?=ps23_money($order['delivery_charge'])?></strong></div><div class="summary-line grand"><span>Estimated total</span><strong><?=ps23_money($order['estimated_total'])?></strong></div><div class="notice warn">Taxes are not calculated in this portal. Final amount is confirmed by the club.</div><h2>Products</h2><?php foreach($order['items'] as $item):?><div class="summary-line"><span><?=ps23_h($item['quantity'].' × '.$item['product_name_snapshot'])?></span><strong><?=ps23_money($item['line_mrp'])?></strong></div><?php endforeach;?></article><aside class="card"><h2>Progress</h2><div class="status-track"><?php foreach($order['events'] as $event):?><div class="status-item"><b><?=ps23_h($event['new_status']?st_label((string)$event['new_status']):ucwords(str_replace('_',' ',(string)$event['event_type'])))?></b><div class="meta"><?=ps23_h($event['created_at'])?></div></div><?php endforeach;?></div><div class="notice">Staff-only review notes are intentionally not shown on public tracking.</div></aside></section><?php endif;?></main><footer class="store-footer">Healthcare Wellness Club • Private request tracking <span class="network-badge" data-network-status role="status" aria-live="polite">Online</span></footer><script src="<?=s24_h(s24_asset('store.js'))?>" defer></script>
<script src="../js/site.js"></script>
</body></html>
